#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<long long>h(n);
for(int i=0;i<n;++i)scanf("%lld",&h[i]);
long long bricks,ladders;scanf("%lld %lld",&bricks,&ladders);
priority_queue<long long,vector<long long>,greater<long long>>pq;
for(int i=0;i+1<n;++i){
long long d=h[i+1]-h[i];
if(d<=0)continue;
pq.push(d);
if((long long)pq.size()>ladders){bricks-=pq.top();pq.pop();
if(bricks<0){printf("%d\n",i);return 0;}}}
printf("%d\n",n-1);return 0;}

